/**
 * Русский словарь — key = китайская строка-источник из кода, value = русский текст.
 *
 * Покрытие: экран провайдера, слэш-команды и /help, /doctor, /config,
 * activity-лейблы, панель статуса, диалог ключа, уведомления TuiApp,
 * welcome/footer/slash-menu (seed). Перевод — только данные: китайские
 * литералы в src/** не меняются.
 *
 * Вклейка: tr() в format-слое и один общий шов — color() (engine/ansi.ts):
 * все панельные строки проходят через него до padding/truncate, поэтому
 * перевод не ломает расчёт ширины. tr() — точное совпадение, поэтому текст
 * моделей и пользователя (markdown/сообщения) не переводится.
 *
 * Строки с `\n`/экранированием в ключ не попадают (сравнение идёт по
 * рантайм-строке); шаблоны с интерполяцией переводятся на месте вызова.
 *
 * @module @deepseek-ai/dsh-tianshu-tui/i18n/ru
 */
/** zh 源串 → ru 译文（缺 key → 渲染层回落源串）。 */
export declare const RU: Readonly<Record<string, string>>;
